//! md's formatting commands — Bold, Italic, Code, Strikethrough, Link, Heading 1–6, Bullet List,
//! Task List, Quote, Indent, Outdent — and the wrap a typed `* _ ` $` makes of a selection, as
//! two pure functions over UTF-16 offsets. Port of md.win `Md.Core.Text.MarkdownFormatting`.
//!
//! The specification is `docs/formatting.md`; the oracle is
//! `tests/fixtures/formatting-vectors.json`, generated by the TypeScript reference in md.win's
//! `tools/formatting-reference/` and copied verbatim into md, md.macOS, md.Android, md.win and
//! here. This is a line-for-line port of md.win's port of that reference: no port may diverge
//! from a vector, and a disputed one is changed in the reference first.
//!
//! A line break is U+000A only — the editor's adapter normalises, as SmartTyping's does. "Blank"
//! is SP, TAB and LF and nothing else, never `char::is_whitespace`. Nothing here is shared with
//! [`super::smart_typing`], which this feature does not touch.
//!
//! **Out-of-range selections.** md.win throws `ArgumentOutOfRangeException` for a selection
//! outside the text; md.macOS, the family's source of truth, clamps both ends into
//! `[0, text.len()]` and answers. This port follows the Mac: it never panics on a selection.

use crate::text::utf16::Utf16Text;

/// One formatting command (`docs/formatting.md`). [`FormatOp::HeadingCycle`] is the phone bar's;
/// the desktop menus use the six levels.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum FormatOp {
    Bold,
    Italic,
    Code,
    Strikethrough,
    Link,
    Heading1,
    Heading2,
    Heading3,
    Heading4,
    Heading5,
    Heading6,
    HeadingCycle,
    BulletList,
    TaskList,
    Quote,
    Indent,
    Outdent,
}

/// One formatting edit: replace `[start, end)` of the **original** text with `text`, then select
/// `[selection_start, selection_end)` of the **resulting** text. Every offset is a UTF-16 code
/// unit.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct FormatEdit {
    pub start: usize,
    pub end: usize,
    pub text: String,
    pub selection_start: usize,
    pub selection_end: usize,
}

impl FormatEdit {
    /// The text after the edit.
    ///
    /// # Panics
    ///
    /// When `[start, end)` does not lie within `original` — an edit applied to a text it was not
    /// computed from (md.win throws `ArgumentOutOfRangeException` there).
    pub fn apply_to(&self, original: &str) -> String {
        self.apply_to_utf16(&Utf16Text::new(original)).to_string_lossy()
    }

    /// [`FormatEdit::apply_to`] on text already in UTF-16 code units.
    ///
    /// # Panics
    ///
    /// As [`FormatEdit::apply_to`].
    pub fn apply_to_utf16(&self, original: &Utf16Text) -> Utf16Text {
        let o = original.units();
        let text: Vec<u16> = self.text.encode_utf16().collect();
        Utf16Text([&o[..self.start], &text, &o[self.end..]].concat())
    }
}

const SP: u16 = 0x20;
const TAB: u16 = 0x09;
const LF: u16 = 0x0A;

const STAR: u16 = b'*' as u16;
const UNDERSCORE: u16 = b'_' as u16;
const BACKTICK: u16 = b'`' as u16;
const DOLLAR: u16 = b'$' as u16;
const TILDE: u16 = b'~' as u16;
const HASH: u16 = b'#' as u16;
const GT: u16 = b'>' as u16;

fn is_blank_unit(c: u16) -> bool {
    c == SP || c == TAB || c == LF
}

fn units(a: &str) -> Vec<u16> {
    a.encode_utf16().collect()
}

fn edit(start: usize, end: usize, text: &[u16], selection_start: usize, selection_end: usize) -> FormatEdit {
    FormatEdit { start, end, text: String::from_utf16_lossy(text), selection_start, selection_end }
}

/// The selection, ordered and clamped into the text as md.macOS does.
fn ordered(len: usize, selection_start: isize, selection_end: isize) -> (usize, usize) {
    let clamp = |o: isize| usize::try_from(o).unwrap_or(0).min(len);
    (clamp(selection_start.min(selection_end)), clamp(selection_start.max(selection_end)))
}

/// The edit `op` makes of the selection, or `None` for none (nothing on the undo stack).
/// `selection_start` and `selection_end` are UTF-16 offsets into `text`, in either order.
pub fn format(text: &str, selection_start: isize, selection_end: isize, op: FormatOp) -> Option<FormatEdit> {
    format_utf16(&Utf16Text::new(text), selection_start, selection_end, op)
}

/// [`format()`] on text already in UTF-16 code units.
pub fn format_utf16(
    text: &Utf16Text,
    selection_start: isize,
    selection_end: isize,
    op: FormatOp,
) -> Option<FormatEdit> {
    let text = text.units();
    let (s, e) = ordered(text.len(), selection_start, selection_end);
    match op {
        FormatOp::Bold => Some(inline(text, s, e, STAR, 2, |a, b| a >= 2 && b >= 2, 2, None)),
        FormatOp::Italic => Some(inline(text, s, e, STAR, 1, |a, b| a % 2 == 1 && b % 2 == 1, 1, Some(UNDERSCORE))),
        FormatOp::Code => Some(inline(text, s, e, BACKTICK, 1, |a, b| a == 1 && b == 1, 1, None)),
        FormatOp::Strikethrough => Some(inline(text, s, e, TILDE, 2, |a, b| a >= 2 && b >= 2, 2, None)),
        FormatOp::Link => Some(link(text, s, e)),
        FormatOp::Heading1 => heading_op(text, s, e, Some(1)),
        FormatOp::Heading2 => heading_op(text, s, e, Some(2)),
        FormatOp::Heading3 => heading_op(text, s, e, Some(3)),
        FormatOp::Heading4 => heading_op(text, s, e, Some(4)),
        FormatOp::Heading5 => heading_op(text, s, e, Some(5)),
        FormatOp::Heading6 => heading_op(text, s, e, Some(6)),
        FormatOp::HeadingCycle => heading_op(text, s, e, None),
        FormatOp::BulletList => bullet_op(text, s, e),
        FormatOp::TaskList => task_op(text, s, e),
        FormatOp::Quote => quote_op(text, s, e),
        FormatOp::Indent => indent_op(text, s, e),
        FormatOp::Outdent => outdent_op(text, s, e),
    }
}

/// Whether `typed` is one of the units whose typing over a selection wraps it.
fn is_wrapping(typed: &[u16]) -> bool {
    matches!(typed, [STAR] | [UNDERSCORE] | [BACKTICK] | [DOLLAR])
}

/// Typing `*`, `_`, `` ` `` or `$` over a non-empty selection wraps it, selection kept on the
/// original text; anything else — a caret, any other text — is `None`, and the keystroke is
/// ordinary typing. The selection is UTF-16 offsets into `text`, in either order.
pub fn wrap_typed(text: &str, selection_start: isize, selection_end: isize, typed: &str) -> Option<FormatEdit> {
    // Asked on every keystroke: a caret or any other character is answered before the text is
    // converted.
    if selection_start == selection_end || !matches!(typed, "*" | "_" | "`" | "$") {
        return None;
    }
    wrap_typed_utf16(&Utf16Text::new(text), selection_start, selection_end, &Utf16Text::new(typed))
}

/// [`wrap_typed`] on text already in UTF-16 code units.
pub fn wrap_typed_utf16(
    text: &Utf16Text,
    selection_start: isize,
    selection_end: isize,
    typed: &Utf16Text,
) -> Option<FormatEdit> {
    let text = text.units();
    let typed = typed.units();
    if selection_start == selection_end || !is_wrapping(typed) {
        return None;
    }
    let (s, e) = ordered(text.len(), selection_start, selection_end);
    if s == e {
        return None; // both ends clamped onto the same offset (md.macOS)
    }
    Some(edit(s, e, &[typed, &text[s..e], typed].concat(), s + 1, e + 1))
}

// ── Inline ──────────────────────────────────────────────────────────────────────────────

fn run_before(text: &[u16], p: usize, ch: u16, floor: usize) -> usize {
    let mut n = 0;
    while p > floor + n && text[p - n - 1] == ch {
        n += 1;
    }
    n
}

fn run_after(text: &[u16], p: usize, ch: u16, ceiling: usize) -> usize {
    let mut n = 0;
    while p + n < ceiling && text[p + n] == ch {
        n += 1;
    }
    n
}

fn trimmed(text: &[u16], s: usize, e: usize) -> (usize, usize) {
    let mut a = s;
    let mut b = e;
    while a < b && is_blank_unit(text[a]) {
        a += 1;
    }
    while b > a && is_blank_unit(text[b - 1]) {
        b -= 1;
    }
    (a, b)
}

fn inline(
    text: &[u16],
    s: usize,
    e: usize,
    ch: u16,
    width: usize,
    present: fn(usize, usize) -> bool,
    remove: usize,
    alternative: Option<u16>,
) -> FormatEdit {
    let marker = vec![ch; width];
    let pair = vec![ch; 2 * width];

    if s == e {
        if run_before(text, s, ch, 0) == width && run_after(text, s, ch, text.len()) == width {
            return edit(s - width, s + width, &[], s - width, s - width);
        }
        return edit(s, s, &pair, s + width, s + width);
    }

    let markers: Vec<u16> = match alternative {
        Some(alt) => vec![ch, alt],
        None => vec![ch],
    };

    // 1. The selection carries the markers itself.
    for &c in &markers {
        let lead = run_after(text, s, c, e);
        let trail = run_before(text, e, c, s);
        if lead + trail >= e - s {
            continue;
        }
        let is_main = c == ch;
        let here = if is_main { present(lead, trail) } else { lead == 1 && trail == 1 };
        let count = if is_main { remove } else { 1 };
        if !here {
            continue;
        }
        let inner = &text[s + count..e - count];
        return edit(s, e, inner, s, s + inner.len());
    }

    // 2. The markers sit just outside the selection.
    for &c in &markers {
        let before = run_before(text, s, c, 0);
        let after = run_after(text, e, c, text.len());
        let is_main = c == ch;
        let here = if is_main { present(before, after) } else { before == 1 && after == 1 };
        let count = if is_main { remove } else { 1 };
        if !here {
            continue;
        }
        let inner = &text[s..e];
        return edit(s - count, e + count, inner, s - count, s - count + inner.len());
    }

    // 3. Wrap what is selected, without its surrounding blanks.
    let (a, b) = trimmed(text, s, e);
    if a == b {
        return edit(s, s, &pair, s + width, s + width);
    }
    edit(a, b, &[&marker, &text[a..b], &marker].concat(), a + width, b + width)
}

fn starts_with_ascii_ignoring_case(text: &[u16], prefix: &str) -> bool {
    if text.len() < prefix.len() {
        return false;
    }
    text.iter().zip(prefix.bytes()).all(|(&c, p)| {
        let c = if (0x41..=0x5A).contains(&c) { c + 32 } else { c };
        c == u16::from(p)
    })
}

fn link(text: &[u16], s: usize, e: usize) -> FormatEdit {
    let (a, b) = trimmed(text, s, e);
    if a == b {
        return edit(s, s, &units("[]()"), s + 1, s + 1);
    }
    let inner = &text[a..b];
    let blank = inner.iter().any(|&c| is_blank_unit(c));
    if !blank
        && (starts_with_ascii_ignoring_case(inner, "http://") || starts_with_ascii_ignoring_case(inner, "https://"))
    {
        return edit(a, b, &[&units("[]("), inner, &units(")")].concat(), a + 1, a + 1);
    }
    let url_at = a + 1 + inner.len() + 2;
    edit(a, b, &[&units("["), inner, &units("](url)")].concat(), url_at, url_at + 3)
}

// ── Lines ───────────────────────────────────────────────────────────────────────────────

#[derive(Clone, Copy, Debug)]
struct Line {
    start: usize,
    end: usize,
}

/// Replace `[at, at + old)` of one line with `text`.
#[derive(Clone, Debug)]
struct LineChange {
    at: usize,
    old: usize,
    text: Vec<u16>,
}

impl LineChange {
    fn new(at: usize, old: usize, text: &str) -> Self {
        LineChange { at, old, text: units(text) }
    }
}

fn line_at(text: &[u16], p: usize) -> Line {
    let mut start = p;
    while start > 0 && text[start - 1] != LF {
        start -= 1;
    }
    let mut end = p;
    while end < text.len() && text[end] != LF {
        end += 1;
    }
    Line { start, end }
}

fn touched_lines(text: &[u16], s: usize, e: usize) -> Vec<Line> {
    let first = line_at(text, s);
    let mut last_pos = e;
    if e > s && e > 0 && text[e - 1] == LF {
        last_pos = e - 1;
    }
    let mut lines = vec![first];
    let mut current = first;
    while current.end < last_pos {
        current = line_at(text, current.end + 1);
        lines.push(current);
    }
    lines
}

fn is_blank_line(line: &[u16]) -> bool {
    line.iter().all(|&c| c == SP || c == TAB)
}

fn indent_end(line: &[u16]) -> usize {
    line.iter().take_while(|&&c| c == SP || c == TAB).count()
}

/// The unit at `i`, or `0` outside the line (C#'s `'\0'`, which no rule compares against).
fn at(line: &[u16], i: usize) -> u16 {
    line.get(i).copied().unwrap_or(0)
}

fn is_digit(c: u16) -> bool {
    (0x30..=0x39).contains(&c)
}

#[derive(Clone, Copy, Debug)]
struct HeadingMarker {
    at: usize,
    level: usize,
    length: usize,
}

fn heading(line: &[u16]) -> Option<HeadingMarker> {
    let mut i = 0;
    while i < 3 && at(line, i) == SP {
        i += 1;
    }
    let mut n = 0;
    while at(line, i + n) == HASH {
        n += 1;
    }
    if !(1..=6).contains(&n) {
        return None;
    }
    let after = i + n;
    if after == line.len() {
        return Some(HeadingMarker { at: i, level: n, length: n });
    }
    if line[after] == SP {
        return Some(HeadingMarker { at: i, level: n, length: n + 1 });
    }
    None
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ListKind {
    Bullet,
    Ordered,
}

#[derive(Clone, Copy, Debug)]
struct ListMarker {
    at: usize,
    kind: ListKind,
    task: bool,
    content_at: usize,
}

fn list_marker_of(line: &[u16]) -> Option<ListMarker> {
    let at_ = indent_end(line);
    let mut i = at_;
    let kind;
    let c = at(line, i);
    if c == b'-' as u16 || c == STAR || c == b'+' as u16 {
        kind = ListKind::Bullet;
        i += 1;
    } else {
        let mut d = 0;
        while d < 9 && is_digit(at(line, i + d)) {
            d += 1;
        }
        if d == 0 {
            return None;
        }
        let p = at(line, i + d);
        if p != b'.' as u16 && p != b')' as u16 {
            return None;
        }
        kind = ListKind::Ordered;
        i += d + 1;
    }
    if i == line.len() {
        return Some(ListMarker { at: at_, kind, task: false, content_at: i });
    }
    if line[i] != SP {
        return None;
    }
    if i + 4 <= line.len() {
        let bx = &line[i + 1..i + 4];
        if bx == units("[ ]") || bx == units("[x]") || bx == units("[X]") {
            let after = i + 4;
            if after == line.len() {
                return Some(ListMarker { at: at_, kind, task: true, content_at: after });
            }
            if line[after] == SP {
                return Some(ListMarker { at: at_, kind, task: true, content_at: after + 1 });
            }
        }
    }
    Some(ListMarker { at: at_, kind, task: false, content_at: i + 1 })
}

#[derive(Clone, Copy, Debug)]
struct QuoteMarker {
    at: usize,
    length: usize,
}

fn quote_of(line: &[u16]) -> Option<QuoteMarker> {
    let mut i = 0;
    while i < 3 && at(line, i) == SP {
        i += 1;
    }
    if at(line, i) != GT {
        return None;
    }
    Some(QuoteMarker { at: i, length: if at(line, i + 1) == SP { 2 } else { 1 } })
}

fn apply_lines(
    text: &[u16],
    s: usize,
    e: usize,
    plan: impl FnOnce(&[&[u16]], &[bool]) -> Vec<Option<LineChange>>,
) -> Option<FormatEdit> {
    let lines = touched_lines(text, s, e);
    let strings: Vec<&[u16]> = lines.iter().map(|l| &text[l.start..l.end]).collect();
    let multi = lines.len() > 1;
    let participating: Vec<bool> = strings.iter().map(|l| !(multi && is_blank_line(l))).collect();
    let changes = plan(&strings, &participating);
    if changes.iter().all(|c| c.as_ref().is_none_or(|c| c.old == 0 && c.text.is_empty())) {
        return None;
    }

    let map = |p: usize| -> usize {
        let mut delta: isize = 0;
        for (line, change) in lines.iter().zip(&changes) {
            let line_delta = change.as_ref().map_or(0, |c| c.text.len() as isize - c.old as isize);
            if p > line.end {
                delta += line_delta;
                continue;
            }
            let Some(ch) = change else { return p.saturating_add_signed(delta) };
            let a = line.start + ch.at;
            if p >= a + ch.old {
                return p.saturating_add_signed(delta + line_delta);
            }
            if p <= a {
                return p.saturating_add_signed(delta);
            }
            return a.saturating_add_signed(delta + ch.text.len() as isize);
        }
        p.saturating_add_signed(delta)
    };

    let mut output: Vec<u16> = Vec::new();
    for (k, (l, change)) in strings.iter().zip(&changes).enumerate() {
        if k > 0 {
            output.push(LF);
        }
        match change {
            Some(c) => {
                output.extend_from_slice(&l[..c.at]);
                output.extend_from_slice(&c.text);
                output.extend_from_slice(&l[c.at + c.old..]);
            }
            None => output.extend_from_slice(l),
        }
    }
    let last = lines[lines.len() - 1];
    Some(edit(lines[0].start, last.end, &output, map(s), map(e)))
}

fn hashes(level: usize) -> String {
    "#".repeat(level) + " "
}

fn set_heading(line: &[u16], level: usize) -> Option<LineChange> {
    if let Some(h) = heading(line) {
        if level == 0 {
            return Some(LineChange::new(h.at, h.length, ""));
        }
        if h.level == level && h.length == level + 1 {
            return None;
        }
        return Some(LineChange::new(h.at, h.length, &hashes(level)));
    }
    if level == 0 {
        return None;
    }
    let indent = indent_end(line);
    let at = if indent <= 3 && !line[..indent].contains(&TAB) { indent } else { 0 };
    Some(LineChange::new(at, 0, &hashes(level)))
}

fn heading_op(text: &[u16], s: usize, e: usize, level: Option<usize>) -> Option<FormatEdit> {
    apply_lines(text, s, e, |lines, on| {
        let target = match level {
            None => {
                let first = (0..lines.len()).find(|&k| on[k]);
                let current = first.map_or(0, |f| heading(lines[f]).map_or(0, |h| h.level));
                match current {
                    0 => 1,
                    1 => 2,
                    2 => 3,
                    _ => 0,
                }
            }
            Some(level) => {
                let all = (0..lines.len()).all(|k| !on[k] || heading(lines[k]).map(|h| h.level) == Some(level));
                if all { 0 } else { level }
            }
        };
        lines.iter().zip(on).map(|(l, &on)| if on { set_heading(l, target) } else { None }).collect()
    })
}

fn bullet_op(text: &[u16], s: usize, e: usize) -> Option<FormatEdit> {
    apply_lines(text, s, e, |lines, on| {
        let all = lines.iter().zip(on).all(|(l, &on)| {
            !on || matches!(list_marker_of(l), Some(ListMarker { kind: ListKind::Bullet, task: false, .. }))
        });
        lines
            .iter()
            .zip(on)
            .map(|(l, &on)| {
                if !on {
                    return None;
                }
                let m = list_marker_of(l);
                if all {
                    // every participating line has a plain bullet here
                    return m.map(|m| LineChange::new(m.at, m.content_at - m.at, ""));
                }
                match m {
                    None => Some(LineChange::new(indent_end(l), 0, "- ")),
                    Some(m) if m.task || m.kind == ListKind::Ordered => {
                        Some(LineChange::new(m.at, m.content_at - m.at, "- "))
                    }
                    Some(_) => None,
                }
            })
            .collect()
    })
}

fn task_op(text: &[u16], s: usize, e: usize) -> Option<FormatEdit> {
    apply_lines(text, s, e, |lines, on| {
        let all = lines.iter().zip(on).all(|(l, &on)| !on || list_marker_of(l).is_some_and(|m| m.task));
        lines
            .iter()
            .zip(on)
            .map(|(l, &on)| {
                if !on {
                    return None;
                }
                let m = list_marker_of(l);
                if all {
                    // every participating line is a task here
                    return m.map(|m| LineChange::new(m.at, m.content_at - m.at, ""));
                }
                let m = match m {
                    None => return Some(LineChange::new(indent_end(l), 0, "- [ ] ")),
                    Some(m) => m,
                };
                if m.task {
                    return None;
                }
                if m.kind == ListKind::Ordered {
                    return Some(LineChange::new(m.at, m.content_at - m.at, "- [ ] "));
                }
                // A bullet: the box goes after its marker and space (a bare `-` gets its space too).
                let mut box_text = vec![l[m.at]];
                box_text.extend(units(" [ ] "));
                Some(LineChange { at: m.at, old: m.content_at - m.at, text: box_text })
            })
            .collect()
    })
}

fn quote_op(text: &[u16], s: usize, e: usize) -> Option<FormatEdit> {
    let lines = touched_lines(text, s, e);
    let multi = lines.len() > 1;
    // Blank lines do not decide "all quoted", but when quoting they get a bare `>`.
    let all = lines.iter().all(|l| {
        let l = &text[l.start..l.end];
        (multi && is_blank_line(l)) || quote_of(l).is_some()
    });
    apply_lines(text, s, e, |ls, _| {
        ls.iter()
            .map(|l| {
                if all {
                    return quote_of(l).map(|q| LineChange::new(q.at, q.length, ""));
                }
                if quote_of(l).is_some() {
                    return None;
                }
                if multi && is_blank_line(l) {
                    return Some(LineChange::new(0, 0, ">"));
                }
                Some(LineChange::new(0, 0, "> "))
            })
            .collect()
    })
}

fn indent_op(text: &[u16], s: usize, e: usize) -> Option<FormatEdit> {
    apply_lines(text, s, e, |_, on| on.iter().map(|&on| on.then(|| LineChange::new(0, 0, "  "))).collect())
}

fn outdent_op(text: &[u16], s: usize, e: usize) -> Option<FormatEdit> {
    apply_lines(text, s, e, |lines, _| {
        lines
            .iter()
            .map(|l| {
                if at(l, 0) == TAB {
                    return Some(LineChange::new(0, 1, ""));
                }
                let n = if at(l, 0) == SP { if at(l, 1) == SP { 2 } else { 1 } } else { 0 };
                (n != 0).then(|| LineChange::new(0, n, ""))
            })
            .collect()
    })
}
